import{_ as i}from"./chunks/ArticleMetadata.1_--bNMz.js";import{_ as s,D as r,o as t,c as n,I as p,w as h,k as l,a as _,R as m,b as u,e as b}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const V=JSON.parse('{"title":"整体架构","description":"","frontmatter":{"title":"整体架构","showArticleMetadata":false,"showComment":false},"headers":[],"relativePath":"open-source/01-dsh-mytable/01-整体架构.md","filePath":"open-source/01-dsh-mytable/01-整体架构.md","lastUpdated":1789997903000}'),f={name:"open-source/01-dsh-mytable/01-整体架构.md"},x=l("h1",{id:"整体架构",tabindex:"-1"},[_("整体架构 "),l("a",{class:"header-anchor",href:"#整体架构","aria-label":'Permalink to "整体架构"'},"​")],-1),k=m('<p><code>dsh-mytable</code> 的核心不是某一个组件，而是服务端插件、客户端工作台和 DSH 宿主之间的协作。</p><h2 id="三个层次" tabindex="-1">三个层次 <a class="header-anchor" href="#三个层次" aria-label="Permalink to &quot;三个层次&quot;">​</a></h2><h3 id="_1-插件入口与打包" tabindex="-1">1. 插件入口与打包 <a class="header-anchor" href="#_1-插件入口与打包" aria-label="Permalink to &quot;1. 插件入口与打包&quot;">​</a></h3><p><code>dsh.plugin.json</code> 声明插件名称、版本和 Web 客户端平台；<code>cordis.patch.yml</code> 负责把插件接入 DSH 配置。<code>build.mjs</code> 使用 esbuild 分别生成服务端入口 <code>lib/index.js</code> 与客户端入口 <code>lib/client.js</code>，最终再通过 npm 包交付。</p><h3 id="_2-服务端能力" tabindex="-1">2. 服务端能力 <a class="header-anchor" href="#_2-服务端能力" aria-label="Permalink to &quot;2. 服务端能力&quot;">​</a></h3><p><code>src/index.ts</code> 注入 DSH 的 <code>webServer</code> 和 <code>sessions</code> 服务，并在 <code>/api/worktable/*</code> 下提供私有协议。主要职责包括：</p><ul><li>列出与搜索工作区文件；</li><li>读取文件并按类型返回正确的 MIME；</li><li>获取 Git 仓库、分支和工作区改动；</li><li>从会话事件中收窄并整理工具调用、输出和 token 统计；</li><li>在宿主依赖允许时注册终端 WebSocket；</li><li>探测外部网页是否允许被 iframe 嵌入。</li></ul><p>服务端会优先通过官方 <code>@deepseek-ai/dsh-home-paths</code> 解析数据目录，不可用时再按 <code>DSH_HOME</code> 与 <code>~/.dsh</code> 规则回退，避免不同 profile 或桌面环境读错数据。</p><h3 id="_3-客户端工作台" tabindex="-1">3. 客户端工作台 <a class="header-anchor" href="#_3-客户端工作台" aria-label="Permalink to &quot;3. 客户端工作台&quot;">​</a></h3><p>客户端入口位于 <code>src/client/index.tsx</code>。它把工作台侧边栏、布局编辑、文件预览、终端、浏览器、Git 改动、任务、提示词空间和 Flowglass 等能力接入 DSH Web UI。</p><p>其中 <code>split.tsx</code> 负责通用分栏引擎，<code>mytable-service.ts</code> 提供第三方插件扩展入口，各类具体窗口则被拆分为 <code>explorer-pane.tsx</code>、<code>browser-pane.tsx</code>、<code>changes-pane.tsx</code>、<code>jobs-pane.tsx</code> 等模块。</p><h2 id="一次典型交互" tabindex="-1">一次典型交互 <a class="header-anchor" href="#一次典型交互" aria-label="Permalink to &quot;一次典型交互&quot;">​</a></h2><ol><li>用户在工作台里选择一个项目和会话。</li><li>客户端根据布局配置创建窗格与标签页。</li><li>文件树、Git 或会话统计通过 <code>/api/worktable/*</code> 请求插件服务端。</li><li>服务端基于会话目录或客户端传入目录解析目标工作区。</li><li>结果回到对应窗格，布局与偏好保存在浏览器本地存储中。</li></ol><p>这种结构让 UI 可以快速组合，同时把文件系统、Git 和终端等高权限能力留在服务端边界内。</p><p>下一篇：<a href="/open-source/01-dsh-mytable/02-分栏工作区模型">分栏工作区模型</a></p>',15);function S(e,q,w,y,P,C){const c=i,d=r("ClientOnly");return t(),n("div",null,[x,p(d,null,{default:h(()=>{var a,o;return[(((a=e.$frontmatter)==null?void 0:a.aside)??!0)&&(((o=e.$frontmatter)==null?void 0:o.showArticleMetadata)??!0)?(t(),u(c,{key:0,article:e.$frontmatter},null,8,["article"])):b("",!0)]}),_:1}),k])}const $=s(f,[["render",S]]);export{V as __pageData,$ as default};
